import { useEffect, useState } from 'react'
export default function Estoque(){const [itens,setItens]=useState([]),[erro,setErro]=useState('');const carregar=()=>fetch('/api/estoque').then(r=>r.ok?r.json():Promise.reject(new Error('Não foi possível carregar o estoque.'))).then(setItens).catch(e=>setErro(e.message));useEffect(()=>{carregar()},[]);const movimentar=async(p,tipo)=>{const quantidade=prompt(`Quantidade para ${tipo.toLowerCase()} em ${p.nome}:`);if(!quantidade)return;const r=await fetch(`/api/estoque/${p.id}/movimentacoes`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({tipo,quantidade})});if(!r.ok){const d=await r.json().catch(()=>({}));alert(d.erro||'Não foi possível atualizar o estoque.');return}carregar()};return <div><div className="section-head"><div><h2>Estoque</h2><div className="muted">Controle de disponibilidade e saldo dos produtos</div></div></div>{erro&&<div className="card" style={{color:'#d32f2f'}}>{erro}</div>}<div className="card" style={{padding:0,overflow:'hidden'}}>{itens.map(p=><div className="list-row" key={p.id}><div style={{flex:1}}><strong>{p.nome}</strong><div className="muted">{p.categoria?.nome}</div></div><div><strong>{p.estoqueAtual}</strong> <span className="muted">mín. {p.estoqueMinimo}</span></div><span className={p.baixo?'pill pill-danger':'pill pill-basil'}>{p.baixo?'Baixo':'Normal'}</span><button className="btn btn-ghost" onClick={()=>movimentar(p,'ENTRADA')}>Entrada</button><button className="btn btn-ghost" onClick={()=>movimentar(p,'SAIDA')}>Saída</button></div>)}{!itens.length&&<div className="empty-state" style={{padding:24}}>Nenhum produto com controle de estoque.</div>}</div></div>}
